#!/usr/bin/env bash
set -eu
cd "$HOME/tg-community-run"
python3 - <<'PY'
import cloudshell as c
host=c.host_and_volume("tg-grh-source-replay")["Instance"]
if host!="i-0e7d3f1a40dbca69c":raise SystemExit("Unexpected EC2 host")
state=c.aws("ec2","describe-instances","--instance-ids",host)["Reservations"][0]["Instances"][0]["State"]["Name"]
if state!="running":raise SystemExit("Instance is "+state+"; no restart requested")
online=c.aws("ssm","describe-instance-information","--filters","Key=InstanceIds,Values="+host)["InstanceInformationList"]
if not any(r["InstanceId"]==host and r["PingStatus"]=="Online" for r in online):raise SystemExit("SSM not online")
c.ssm(host, 'systemd-run --quiet --wait --pipe --collect --unit=tg-warm-patch-probe --uid=grhreplay --gid=grhreplay -p CPUQuota=80% -p CPUWeight=1 -p Nice=19 -p IOWeight=1 -p MemoryHigh=4G -p MemoryMax=6G -p MemorySwapMax=0 -p RuntimeMaxSec=240 -p TasksMax=48 -p LimitFSIZE=134217728 -p KillMode=control-group -p TimeoutStopSec=3 -- /usr/bin/python3 -B -c \'import base64,gzip,hashlib;source=gzip.decompress(base64.b64decode(\'"\'"\'\'"\'"\'));assert hashlib.sha256(source).hexdigest()==\'"\'"\'0b677967398148d342c99eaa481b7a6defc839a314bb71132f023de31b0fbfe9\'"\'"\';exec(compile(source,\'"\'"\'warm_probe.py\'"\'"\',\'"\'"\'exec\'"\'"\'))\' --commit d6b1bfd523e2c54b6e4bb72844deeddf8341879a --tree ddc22b3144b7147ce91c5c767690d9d56aac50ee --attempt 33006912706042b49c1ddbc13515a4fb --module Lib.Shimura.ThetaNormality.NormalGeneration --patch-commit 78153fd331c2ff93b2d08cd1d01ecdd7d257aea2 --sha256 93203bc976d2b82768980e54951e128c4e0710660e35f0e320706c920c8e4b72 --data ', timeout=300)
PY
